describe('Internal Links Navigation', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should open internal links in the same tab', () => {
    cy.get('a[href*="/about"]').first().then(($link) => {
      const href = $link.attr('href');
      expect($link).not.to.have.attr('target', '_blank');
      expect($link).not.to.have.attr('target', '_new');
    });

    cy.get('a[href*="/about"]').first().click();
    cy.url().should('include', '/about');
    cy.go('back');
  });

  it('should navigate through multiple internal links without opening new tabs', () => {
    cy.get('a[href*="/services"]').first().click();
    cy.url().should('include', '/services');

    cy.get('a[href*="/contact"]').first().click();
    cy.url().should('include', '/contact');

    cy.get('a[href*="/"]').first().click();
    cy.url().should('not.include', '/contact');
  });

  it('should not open external links in the same tab', () => {
    cy.get('a[href^="http"]').first().then(($link) => {
      const href = $link.attr('href');
      if (!href.includes(Cypress.config().baseUrl)) {
        expect($link).to.have.attr('target', '_blank');
      }
    });
  });

  it('should handle relative internal links correctly', () => {
    cy.get('a[href^="/"]').each(($link) => {
      const href = $link.attr('href');
      expect(href).to.match(/^\//);
      expect($link).not.to.have.attr('target', '_blank');
    });
  });

  it('should maintain page state when navigating internal links', () => {
    cy.get('input[type="text"]').first().type('test data');
    cy.get('a[href*="/about"]').first().click();
    cy.url().should('include', '/about');
    cy.go('back');
    cy.get('input[type="text"]').first().should('have.value', 'test data');
  });

  it('should handle internal links with hash fragments in the same tab', () => {
    cy.get('a[href*="#"]').first().then(($link) => {
      const href = $link.attr('href');
      if (href.startsWith('#') || href.includes('/#')) {
        expect($link).not.to.have.attr('target', '_blank');
      }
    });

    cy.get('a[href*="#section"]').first().click({ force: true });
    cy.url().should('include', '#section');
  });
});
